const SUMMON_FORMS={
 wolf:{name:'霊狼',desc:'素早く接近して1体を攻撃。移動220・射程65・0.9秒ごとに55%。',speed:220,range:65,interval:.9,power:.55,size:85,element:4,material:null},
 owl:{name:'星羽の梟',desc:'離れた位置から1体を攻撃。移動190・射程280・1.2秒ごとに65%。',speed:190,range:280,interval:1.2,power:.65,size:85,element:2,material:'r2e7:0'},
 rock:{name:'岩甲の霊獣',desc:'接近し、標的の周囲90へ衝撃波。移動140・射程80・1.8秒ごとに100%。',speed:140,range:80,interval:1.8,power:1,size:110,element:5,splash:90,material:'r1e4:0'}
};
function summonUnlocked(id,character=p){return id==='wolf'||character.summonUnlocks?.includes(id)}
function summonPlan(){return p.summonPlan||['wolf','wolf','wolf']}
const rosterValidateBase=validateSave;validateSave=data=>{let out=rosterValidateBase(data),src=data.p;
 if(src.summonUnlocks!==undefined){if(!Array.isArray(src.summonUnlocks)||src.summonUnlocks.length>2||new Set(src.summonUnlocks).size!==src.summonUnlocks.length||src.summonUnlocks.some(id=>!['owl','rock'].includes(id))||src.summonUnlocks.length&&(out.p.campaign?.rank||1)<5)throw Error('召喚獣の習得が不正です');out.p.summonUnlocks=[...src.summonUnlocks];}
 if(src.summonPlan!==undefined){if(!Array.isArray(src.summonPlan)||src.summonPlan.length!==3||src.summonPlan.some(id=>!Object.hasOwn(SUMMON_FORMS,id)||!summonUnlocked(id,out.p)))throw Error('召喚編成が不正です');out.p.summonPlan=[...src.summonPlan];}return out;
};
function learnSummon(id){let form=SUMMON_FORMS[id];if(!form?.material||!villageOpen||campaign().rank<5||summonUnlocked(id)||(campaign().materials[form.material]||0)<8)return false;let result=worldTransaction(()=>{campaign().materials[form.material]-=8;p.summonUnlocks??=[];p.summonUnlocks.push(id);});if(result)showSummonRoster();return result;}
function setSummonSlot(index,id){if(!villageOpen||campaign().rank<5||!Number.isInteger(index)||index<0||index>2||!Object.hasOwn(SUMMON_FORMS,id)||!summonUnlocked(id))return false;return withGameImages(()=>{let result=worldTransaction(()=>{p.summonPlan=[...summonPlan()];p.summonPlan[index]=id;});if(result){resetCompanions();showSummonRoster(index);}return result;},()=>showSummonRoster(index),[...BASE_GAME_IMAGES,wolfSheet,owlSheet,rockBeastSheet]);}
function showSummonRoster(focus=0){worldMenu('召喚編成','<p>通常攻撃で1枠目から順に召喚。最大3体。同じ種類を複数選ぶこともできます。編成変更は村・ランク5から。</p><div class="summon-slots">'+summonPlan().map((id,i)=>'<label>召喚枠 '+(i+1)+'<select aria-label="召喚枠 '+(i+1)+'" onchange="setSummonSlot('+i+',this.value)" '+(!villageOpen||campaign().rank<5?'disabled':'')+'>'+Object.entries(SUMMON_FORMS).map(([key,f])=>'<option value="'+key+'" '+(id===key?'selected':'')+' '+(!summonUnlocked(key)?'disabled':'')+'>'+f.name+'</option>').join('')+'</select></label>').join('')+'</div><div class="summon-roster">'+Object.entries(SUMMON_FORMS).map(([id,form])=>'<section class="job-detail"><h3>'+form.name+'</h3><p>'+form.desc+'</p>'+(summonUnlocked(id)?'<small>習得済み</small>':materialTile(form.material,8)+'<button onclick="learnSummon(\''+id+'\')" '+(!villageOpen||campaign().rank<5||(campaign().materials[form.material]||0)<8?'disabled':'')+'>素材で習得</button>')+'</section>').join('')+'</div><button onclick="showJobHall()">転職所へ戻る</button>','summonRoster');menuFocusElement($('card').querySelectorAll('.summon-slots select')[focus]);}
const rosterCallBase=callCompanion;callCompanion=dragon=>{let count=companions.length,occupied=new Set(companions.map(c=>c.summonSlot)),slot=[0,1,2].find(i=>!occupied.has(i)),result=rosterCallBase(dragon);if(result&&!dragon&&companions.length>count){let pet=companions.at(-1),id=summonPlan()[slot],form=SUMMON_FORMS[id];Object.assign(pet,{summonSlot:slot,offset:slot,form:id,name:form.name,speed:form.speed,range:form.range,interval:form.interval,power:form.power,size:form.size,element:form.element,splash:form.splash||0});}return result;};
const rosterImagesBase=characterGameImages;characterGameImages=character=>{let images=rosterImagesBase(character);if((character?.job??character?.type)%8===6){if(character.summonPlan?.includes('owl'))images.push(owlSheet);if(character.summonPlan?.includes('rock'))images.push(rockBeastSheet);}return images;};
const rosterChangeBase=changeJob;changeJob=id=>{if(id%8!==6)return rosterChangeBase(id);return withGameImages(()=>rosterChangeBase(id),()=>showJobHall(id),[...BASE_GAME_IMAGES,wolfSheet,dragonSheet,owlSheet,rockBeastSheet]);};
const rosterCloseBase=closePanel;closePanel=(...args)=>{if(menuSurface==='summonRoster'){showJobHall();return;}return rosterCloseBase(...args)};
PROFESSIONS[6].trait='通常攻撃で編成した味方を30秒召喚（最大3体）。3体いる間は照準付近の敵へ集中攻撃を指示。';
PROFESSIONS[6].desc='編成した3体を呼び直し、8秒間、仲間の攻撃間隔を半分にする。';
ADVANCED_JOBS[6][1]='召喚獣の持続時間が45秒になる。';
JOB_ACTIONS[6][1]='味方を呼び戻す／自動攻撃へ戻す。通常攻撃で召喚と集中攻撃の指示。転職所で3枠を編成。';
